css:
.cctc-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.cctc-root,.cctc-root *,.cctc-root *::before,.cctc-root *::after{box-sizing:border-box}
.cctc-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.cctc-root img{display:block;border:0;max-width:none}
.cctc-root > [data-node-id]{will-change:transform}
.cctc-root [hidden]{display:none!important}
.cctc-root [data-sh-theme="dark"]{display:none!important}
.cctc-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.cctc-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.cctc-root .n427_4396{word-break:break-word;align-content:stretch;display:flex;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:420;gap:20px;align-items:center;line-height:normal;font-style:normal;padding-top:15px;padding-bottom:15px;position:relative;flex-shrink:0;font-size:18px;width:596px}
.cctc-root .n427_4396::after{content:"";position:absolute;inset:0;border:1px solid color-mix(in srgb, var(--wa-line, rgb(0 0 0)) 10%, transparent);border-radius:inherit;border-width:0 0 1px 0;pointer-events:none}
.cctc-root .n427_4397{overflow:hidden;position:relative;flex-shrink:0;color:var(--wa-point, #0073ff);text-overflow:ellipsis;width:95px;white-space:nowrap}
.cctc-root .n427_4398{position:relative;flex-shrink:0;color:var(--wa-text-sub, #434859);width:481px}
.cctc-root [data-node-id="427:1289"],.cctc-root [data-node-id="427:1317"]{height:auto!important}
.cctc-root [data-node-id="427:1537"]{width:100%!important}
.cctc-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.cctc-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.cctc-root > [data-node-id="427:4307"]{width:1010px!important;height:909px!important}
.cctc-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.cctc-root[data-theme="dark"] > [data-node-id]{background:linear-gradient(180deg,var(--wa-bg, #111720) 0%,var(--wa-bg, #0b0e13) 100%)!important}
.cctc-root[data-theme="dark"] [data-name="3D Scene"] img{filter:brightness(.88) saturate(.95) contrast(1.04)}
.cctc-root[data-theme="dark"] [data-name="Diagram Title Patch"]{background:linear-gradient(90deg,var(--wa-point, #3d2f63) 0%,var(--wa-point, #1b2a38) 50%,var(--wa-point, #352c5d) 100%)!important;border-color:var(--wa-point, #7d7bf0)!important}
.cctc-root[data-theme="dark"] [data-name="Diagram Title Patch"] p{color:var(--wa-text, #eef0fb)!important}
.cctc-root[data-theme="dark"] [data-name="Side Rail"] > [data-name="Body"]{background:linear-gradient(180deg,var(--wa-surface, #151920) 47%,color-mix(in srgb, var(--wa-surface, rgb(21 25 32)) 90%, transparent) 100%)!important;border-right-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 6%, transparent)!important}
.cctc-root[data-theme="dark"] [data-name^="Panel/"]:not([data-name="Panel/File Open"]),.cctc-root[data-theme="dark"] [data-name="Popup/Detail"]{box-shadow:inset 1px 0 0 rgba(255,255,255,.04),0 12px 30px rgba(0,0,0,.35)}
.cctc-root[data-theme="dark"] [data-name="Icon Button"]{box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.cctc-root[data-theme="dark"] .n427_4396::after{border-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 10%, transparent)}
.cctc-root[data-theme="dark"] .n427_4397{color:var(--wa-point, #5ea2ff)}
.cctc-root[data-theme="dark"] .n427_4398{color:var(--wa-text-sub, #c3cad6)}
